<script setup>import { computed } from 'vue';import { Search } from 'lucide-vue-next';import ConversationListItem from './ConversationListItem.vue';const props=defineProps({conversations:Array,selectedId:String,search:String,filter:String});const emit=defineEmits(['select','update:search','update:filter']);const filters=['All','Unread','Telegram','WhatsApp','Web'];const filtered=computed(()=>props.conversations.filter(c=>{const q=props.search.toLowerCase();return(!q||`${c.name} ${c.preview}`.toLowerCase().includes(q))&&(props.filter==='All'||(props.filter==='Unread'?c.unread:c.channel===props.filter))}))</script>
<template><aside class="list"><div class="tools"><label><Search :size="16"/><input aria-label="Search conversations" placeholder="Search conversations" :value="search" @input="emit('update:search',$event.target.value)"/></label><div class="filters"><button v-for="f in filters" :key="f" :class="{active:filter===f}" @click="emit('update:filter',f)">{{f}}</button></div></div><div class="scroll"><ConversationListItem v-for="c in filtered" :key="c.id" :conversation="c" :active="selectedId===c.id" @click="emit('select',c.id)"/><div v-if="!filtered.length" class="empty">No conversations match.</div></div></aside></template>
<style scoped>.list{width:350px;flex:none;border-right:1px solid #eef0f5;background:#fbfbfd;display:flex;flex-direction:column;min-height:0}.tools{padding:14px 15px 11px}.tools label{display:flex;align-items:center;gap:8px;background:#fff;border:1px solid var(--border);border-radius:10px;padding:0 11px;color:var(--muted)}.tools input{border:0;padding:9px 0;font-size:13px;outline:0}.filters{display:flex;gap:6px;overflow-x:auto;margin-top:10px}.filters button{border:1px solid var(--border);background:#fff;padding:5px 10px;border-radius:16px;font-size:11.5px;font-weight:600}.filters button.active{background:var(--primary);border-color:var(--primary);color:#fff}.scroll{overflow-y:auto;flex:1}@media(max-width:1050px){.list{width:310px}}@media(max-width:760px){.list{width:100%;border:0}.list.hidden-mobile{display:none}}</style>
